namespace sv_198a6c6e07934ca1a412600add670ab7.Client.Services;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    string Description,
    DateTimeOffset Timestamp);

namespace sv_198a6c6e07934ca1a412600add670ab7.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;

namespace sv_198a6c6e07934ca1a412600add670ab7.Client.Services;

/// <summary>
/// WebAssembly-side implementation that calls the server API.
/// </summary>
public sealed class ShipmentHttpClient(HttpClient http) : IShipmentService
{
    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var shipment = await http.GetFromJsonAsync<Shipment>(
            $"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        return shipment ?? throw new InvalidOperationException("Shipment not found.");
    }
}

using sv_198a6c6e07934ca1a412600add670ab7.Client.Services;

namespace sv_198a6c6e07934ca1a412600add670ab7.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 7, 3, 14, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 6, 28, 9, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", new DateTimeOffset(2026, 6, 28, 18, 30, 0, TimeSpan.Zero)),
                new("Departed Memphis hub", new DateTimeOffset(2026, 6, 29, 6, 0, 0, TimeSpan.Zero)),
            }),

        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 6, 27, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 6, 25, 10, 0, 0, TimeSpan.Zero)),
                new("In transit", new DateTimeOffset(2026, 6, 26, 8, 0, 0, TimeSpan.Zero)),
                new("Out for delivery", new DateTimeOffset(2026, 6, 27, 7, 0, 0, TimeSpan.Zero)),
                new("Delivered", new DateTimeOffset(2026, 6, 27, 11, 45, 0, TimeSpan.Zero)),
            }),

        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 7, 5, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", new DateTimeOffset(2026, 6, 29, 15, 0, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_198a6c6e07934ca1a412600add670ab7.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>

            <dt>Location</dt>
            <dd>@_shipment.Location</dd>

            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.Updates)
            {
                <li>
                    <strong>@update.Timestamp.ToString("g")</strong> &mdash; @update.Description
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;
    private string? _lastLoadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        // If the tracking number changed (navigation), cancel any in-flight request
        if (string.Equals(_lastLoadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase)
            && _shipment is not null)
        {
            return;
        }

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any previous pending request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _lastLoadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled (navigation or dispose) — do nothing
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || !ct.IsCancellationRequested)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryLoad()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

